// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        Reverter reverter = new Reverter();
        vm.deal(address(c), amount);
        bool ok;
        vm.prank(address(this));
        try c.withdrawAll(address(reverter)) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract Reverter {
    receive() external payable { revert(); }
}
